INSERT INTO changelog (title, body, created_at) VALUES ('Фірмовий PDF пропозиції і порядок у конекторі Meta', 'PDF пропозиції з лабораторії тепер — ОДИН фірмовий шаблон для всіх клієнтів: A4 вертикально (зручно з телефона), темний у стилі сайту, синій акцент. Сторінки: обкладинка з рекомендованим пакетом → проблема і «чому це важливо саме для вас» → що отримаєте → що входить → як ми це зробимо (етапи) → пакети картками → чому вигідно (3 цифри) → рахунок → бонуси → наступний крок. Порожні розділи пропускаються. Кнопка «PDF пропозиції» в лабораторії, Джері — інструмент lab_proposal_pdf (може одразу скинути тобі в Telegram).
Промпт для Claude (кнопка «Промпт» → пропозиція) тепер описує цей самий дизайн і структуру і містить усі цифри: послуги, пакети, вигоду, рахунок, етапи. У чаті Claude вийде така сама пропозиція, тільки красивіша.
Конектор Meta: компактна шапка (оновити, токен), дві вкладки — «Кабінети» і «Заявки». Непривʼязані кабінети і чужі сторінки згорнуті, будь-який можна «Сховати» (приховані — окремим списком, сховані сторінки не перевіряються на заявки).', datetime('now'));
